import re
from datetime import datetime


def dedupe_contacts(rows):
    """Normalize, merge, and dedupe CRM contact rows per the data team's rules.

    Takes a list of dicts (first_name, last_name, email, phone, zip, tags,
    opted_out, updated, source) and returns one dict per person, in order of
    each person's earliest row in the input. Input rows are not modified.
    """
    GMAIL_DOMAINS = {"gmail.com", "googlemail.com"}
    DATE_FORMATS = ("%Y-%m-%d", "%m/%d/%Y", "%Y-%m-%dT%H:%M:%S")
    OPT_OUT_VALUES = {"y", "yes", "true", "1"}

    # ---------- helpers ----------

    def text(row, key):
        v = row.get(key)
        return "" if v is None else str(v)

    def is_digits(s):
        return s != "" and all(c in "0123456789" for c in s)

    def norm_email(raw):
        # Rule 1
        m = re.search(r"<([^<>]*)>", raw)
        if m:
            raw = m.group(1)
        e = raw.strip().lower()
        if e.count("@") == 1:
            local, domain = e.split("@")
            if domain in GMAIL_DOMAINS:
                local = local.replace(".", "").split("+", 1)[0]
                e = local + "@gmail.com"
        return e

    def email_valid(e):
        # Rule 2
        if e.count("@") != 1:
            return False
        local, domain = e.split("@")
        return (
            bool(local)
            and "." in domain
            and not domain.startswith(".")
            and not domain.endswith(".")
        )

    def norm_phone(raw):
        # Rule 3
        s = raw.lower()
        cuts = [s.find(marker) for marker in ("x", "ext", "#")]
        cuts = [c for c in cuts if c != -1]
        if cuts:
            s = s[: min(cuts)]
        digits = "".join(c for c in s if c in "0123456789")
        if len(digits) == 11 and digits[0] == "1":
            digits = digits[1:]
        return digits

    def phone_valid(p):
        return len(p) == 10 and p[0] not in "01"

    def norm_zip(raw):
        # Rule 4
        z = raw.strip()
        if "-" in z:
            z = z.split("-", 1)[0].strip()
        if is_digits(z) and len(z) == 4:
            z = "0" + z
        return z if is_digits(z) and len(z) == 5 else ""

    def norm_name(raw):
        # Rule 5
        n = raw.strip()
        if n.isupper() or n.islower():
            return n.title()
        return n

    def parse_updated(raw):
        # Rule 6
        s = raw.strip()
        for fmt in DATE_FORMATS:
            try:
                return datetime.strptime(s, fmt)
            except ValueError:
                continue
        # Spec says updated is never empty/malformed; if it is, treat it as
        # the oldest possible date so it never wins "most recent".
        return datetime.min

    def norm_tags(raw):
        # Rule 8 (+ rule 11 cleanup)
        return {t.strip().lower() for t in re.split(r"[;,]", raw) if t.strip()}

    def fmt_date(d):
        return "%04d-%02d-%02d" % (d.year, d.month, d.day)

    # ---------- normalize rows, drop unusable ones (rule 9) ----------

    recs = []
    for idx, row in enumerate(rows):
        email = norm_email(text(row, "email"))
        phone = norm_phone(text(row, "phone"))
        ev, pv = email_valid(email), phone_valid(phone)
        if not ev and not pv:
            continue
        recs.append(
            {
                "idx": idx,
                "first_name": norm_name(text(row, "first_name")),
                "last_name": norm_name(text(row, "last_name")),
                "email": email if ev else "",
                "phone": phone if pv else "",
                "zip": norm_zip(text(row, "zip")),
                "tags": norm_tags(text(row, "tags")),
                "opted_out": text(row, "opted_out").strip().lower() in OPT_OUT_VALUES,
                "updated": parse_updated(text(row, "updated")),
                "source": text(row, "source").strip().lower(),
            }
        )

    # ---------- group rows into people (rule 10, transitive via union-find) ----------

    parent = list(range(len(recs)))

    def find(i):
        while parent[i] != i:
            parent[i] = parent[parent[i]]
            i = parent[i]
        return i

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            if ra < rb:
                parent[rb] = ra
            else:
                parent[ra] = rb

    key_owner = {}
    for i, r in enumerate(recs):
        keys = []
        if r["email"]:
            keys.append(("email", r["email"]))
        if r["phone"] and r["last_name"]:
            keys.append(("phone", r["phone"], r["last_name"].lower()))
        for k in keys:
            if k in key_owner:
                union(i, key_owner[k])
            else:
                key_owner[k] = i

    groups = {}  # root -> list of recs; insertion order == earliest row order (rule 12)
    for i, r in enumerate(recs):
        groups.setdefault(find(i), []).append(r)

    # ---------- build one output dict per person (rule 11) ----------

    def pick(group, field):
        cands = [r for r in group if r[field]]
        if not cands:
            return ""
        best = max(
            cands,
            key=lambda r: (r["source"] == "manual", r["updated"], -r["idx"]),
        )
        return best[field]

    out = []
    for group in groups.values():
        all_tags = set()
        for r in group:
            all_tags |= r["tags"]
        out.append(
            {
                "first_name": pick(group, "first_name"),
                "last_name": pick(group, "last_name"),
                "zip": pick(group, "zip"),
                "email": pick(group, "email"),
                "phone": pick(group, "phone"),
                "source": pick(group, "source"),
                "tags": ";".join(sorted(all_tags)),
                "opted_out": "Y" if any(r["opted_out"] for r in group) else "N",
                "updated": fmt_date(max(r["updated"] for r in group)),
            }
        )
    return out
```

A few notes on judgment calls, in case your data person wants to adjust:

- **Extension markers:** I cut at the *earliest* occurrence of `x`, `ext`, or `#`, so `"617-555-0100 ext 4"` and `"617-555-0100x4"` both work. Note this means a phone like `"6175550100 (fax)"` would also be truncated at the `x` in "fax" — that still yields the right 10 digits here, but it's worth knowing.
- **Display names:** if an email somehow has more than one `<...>` chunk, the first one is used.
- **Unparseable `updated`:** the spec says this can't happen, so rather than crash the whole run the night before send, a bad value is treated as the oldest possible date (it never wins "most recent" and never sets the group's `updated` unless every row in the group is bad). If you'd rather fail loudly, change the `return datetime.min` to `raise ValueError(...)`.
- **Tie-breaking** for every picked field is exactly: `manual` source → most recent `updated` → earliest input row. Validity/non-emptiness is checked per field, so one row can contribute the email while another contributes the ZIP.
- **Phone-based matching** requires a non-empty last name on both rows; two rows sharing a phone but with no last name are not merged (per rule 10). Email matches don't need a last name.

Since the opt-out flag is "Y" if *any* row in the merged group opted out, anyone who ever unsubscribed under any of their emails/phones will be flagged — you'll want to filter `opted_out == "N"` before sending.
